      --accent: #00B4D8;
      --accent-hover: #0077B6;
      --accent-glow: rgba(0,180,216,0.18);
      --border: rgba(255,255,255,0.08);
      --border-strong: rgba(255,255,255,0.14);
      --success: #6CC24A;
      --error: #EF4444;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --transition-fast: 150ms ease;
      --transition-base: 250ms cubic-bezier(0.16,1,0.3,1);
      --transition-slow: 350ms cubic-bezier(0.16,1,0.3,1);
    }

    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', sans-serif;
      background: var(--bg-deep);
      color: var(--foreground);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    h1, h2, h3, h4, h5, h6 {
      font-family: 'Poppins', sans-serif;
      font-weight: 700;
      line-height: 1.2;
      letter-spacing: -0.02em;
    }
    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
    ul { list-style: none; }

    .skip-link {
      position: absolute; top: -40px; left: 0;
      background: var(--accent); color: #000; padding: 8px 16px;
      font-weight: 600; border-radius: 0 0 var(--radius-sm) 0;
      z-index: 10000; transition: top var(--transition-fast);
    }
    .skip-link:focus { top: 0; }

    .container {
      width: 100%; max-width: 1280px; margin: 0 auto;
      padding-left: 24px; padding-right: 24px;
    }
    @media (min-width: 768px) { .container { padding-left: 32px; padding-right: 32px; } }
